const newline = readNewline(input, pos);
if (newline !== null) {
  // Advance line/column across the terminator first, so the next record
  // picks up the correct starting line.
  lineStart = pos + newline.length;
  currentLine += countLines(newline);
  pos += newline.length;
  finishRecord();
  continue;
}
